from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer
from pathlib import Path
from urllib.parse import urlparse,parse_qs
import json
from src.retrieval import RuleRepository
from src.normalization.dictionary import TechnologyDictionary
ROOT=Path(__file__).resolve().parents[2]
HTML='''<!doctype html><meta charset="utf-8"><title>JobGuts</title><style>body{margin:0;background:#101010;color:#f4f4f4;font:16px Arial}.w{max-width:1050px;margin:auto;padding:28px}.nav{display:flex;justify-content:space-between}.help,button{background:#eee;color:#111;border:0;border-radius:9px;padding:11px 16px;font-weight:bold}.hero{padding:55px 0;display:grid;grid-template-columns:1fr 1fr;gap:25px}h1{font-size:52px;margin:0}.muted{color:#aaa}.card{background:#191919;border:1px solid #444;border-radius:16px;padding:20px}.stats{display:flex;gap:10px}.stat{flex:1;background:#111;padding:14px;border-radius:10px}.num{font-size:28px;font-weight:bold}.search{display:flex;gap:8px;margin-top:22px}input{flex:1;padding:13px;border-radius:9px;border:0}.grid{display:grid;grid-template-columns:1fr 1fr;gap:18px}.rule,.e{padding:12px 0;border-bottom:1px solid #333}.pill{background:#333;padding:4px 8px;border-radius:20px}.modal{position:fixed;inset:0;background:#000c;display:flex;align-items:center;justify-content:center}.modal[hidden]{display:none}.dialog{width:min(760px,90%);background:#1b1b1b;border:1px solid #666;border-radius:16px;padding:24px;position:relative}.x{position:absolute;right:12px;top:8px;background:none;color:#fff;font-size:28px}.dialog img{width:100%;max-height:280px;object-fit:contain;background:#090909}@media(max-width:700px){.hero,.grid{grid-template-columns:1fr}h1{font-size:38px}}</style><main class=w><nav class=nav><b>JobGuts / skill intelligence</b><button onclick="openG()">?</button></nav><section class=hero><div><p class=muted>APRlORI · EVIDENCE-FIRST</p><h1>다음에 검토할<br>기술을 찾습니다.</h1><p class=muted>채용공고 기술 조합과 실제 근거 공고를 함께 보여줍니다.</p><div class=search><input id=s value=TensorFlow><button onclick=go()>추천 보기</button></div></div><div class=card><p class=muted>CURRENT DATASET</p><h2>40,348 postings</h2><div class=stats><div class=stat><b class=num>17,796</b><br>transactions</div><div class=stat><b class=num>694</b><br>rules</div><div class=stat><b class=num>8</b><br>tests</div></div></div></section><section class=grid><div class=card><p class=muted>RECOMMENDATIONS</p><div id=r>기술을 입력하세요.</div></div><div class=card><p class=muted>EVIDENCE POSTINGS</p><div id=e>근거 공고를 표시합니다.</div></div></section></main><div id=m class=modal hidden><div class=dialog><button class=x onclick=closeG()>×</button><small id=step></small><h2 id=title></h2><p id=desc class=muted></p><img src=/assets/skill-graph.png alt="기술 연결 그래프"><p class=muted>다음 단계로 자동 전환됩니다.</p></div></div><script>let a=[['1 / 3','기술 입력','검토할 기술을 입력하면 기술 사전으로 표기를 확인합니다.'],['2 / 3','규칙 분석','저장된 규칙에서 support, confidence, interest를 조회합니다.'],['3 / 3','근거 공고','추천 기술과 함께 나타난 실제 공고와 기술 연결 그래프를 확인합니다.']],i=0,t;function show(){step.textContent=a[i][0];title.textContent=a[i][1];desc.textContent=a[i][2];t=setTimeout(()=>{if(++i<3)show();else closeG()},4000)}function openG(){i=0;m.hidden=false;show()}function closeG(){clearTimeout(t);m.hidden=true}async function go(){let d=await fetch('/api/recommend?skills='+encodeURIComponent(s.value)).then(x=>x.json());r.innerHTML=(d.recommendations||[]).map(x=>`<div class=rule><span class=pill>${x.antecedent[0]}</span> → <span class=pill>${x.consequent[0]}</span><br><small>support ${x.support.toFixed(4)} · confidence ${x.confidence.toFixed(4)} · interest ${x.interest.toFixed(4)}</small></div>`).join('')||d.next_action||'규칙 없음';e.innerHTML=(d.evidence_postings||[]).map(x=>`<div class=e><b>${x.title||'제목 없음'}</b><br><small>${x.source} · ${x.job_id}</small></div>`).join('')||'근거 공고 없음'}go();window.onload=openG;</script>'''
class App(BaseHTTPRequestHandler):
 def do_GET(self):
  u=urlparse(self.path)
  if u.path=='/': self.send_response(200);self.send_header('Content-Type','text/html; charset=utf-8');self.end_headers();self.wfile.write(HTML.encode());return
  if u.path=='/assets/skill-graph.png': self.send_response(200);self.send_header('Content-Type','image/png');self.end_headers();self.wfile.write((ROOT/'src/service/assets/skill-graph.png').read_bytes());return
  if u.path=='/api/recommend':
   raw=parse_qs(u.query).get('skills',[''])[0];d=TechnologyDictionary.from_json(ROOT/'configs/tech_dictionary.json');skills=[d.canonicalize(x.strip()) or x.strip() for x in raw.split(',') if x.strip()];data=RuleRepository(ROOT/'artifacts/week12_top_rules.json',ROOT/'data/processed/postings_normalized.jsonl').recommend(skills);self.send_response(200);self.send_header('Content-Type','application/json');self.end_headers();self.wfile.write(json.dumps(data,ensure_ascii=False).encode());return
  self.send_error(404)
if __name__=='__main__': ThreadingHTTPServer(('127.0.0.1',8765),App).serve_forever()
